    }

    function run(address recipient) public payable {
        require(recipient != address(0));
        require(address(c).balance > 0);

        // Make this contract the owner by depositing, then checking the observable owner getter.
        if (address(c).balance == 0) {
            payable(address(c)).transfer(1 wei);
        }
        require(c.owner() == address(this));

        uint256 contractBalance = address(c).balance;
        uint256 recipientBalanceBefore = recipient.balance;

        bool reverted;
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(!reverted && address(c).balance == 0 && recipient.balance == recipientBalanceBefore + contractBalance);
    }

    receive() external payable {}
}

