    constructor(C _c) {
        c = _c;
        payable(_c).transfer(address(this).balance);
    }

    receive() external payable {}

    function run(address recipient) public payable {
        address owner = c.owner();
        uint256 balanceBefore = address(c).balance;

        bool reverted = !(msg.sender == owner);
        if (msg.sender == owner) {
            try c.withdrawAll(recipient) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.withdrawAll(recipient) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        uint256 balanceAfter = address(c).balance;

        if (msg.sender != owner) {
            assert(reverted && balanceAfter == balanceBefore);
        } else {
            assert(!reverted && balanceAfter == 0);
        }
    }
